export const CURRENT_PROTOCOL_VERSION="2026-05-01";export const SUPPORTED_PROTOCOL_VERSIONS=["2026-05-01"];export const DEPRECATED_PROTOCOL_VERSIONS=[];export const PROTOCOL_VERSION_HEADER="Blocks-Protocol-Version";export const SDK_VERSION="0.1.27";export function isProtocolVersionSupported(O){return SUPPORTED_PROTOCOL_VERSIONS.includes(O)}